minimal:
[data-ui-style="minimal"] {
--radius: 6px;
  --radius-sm: 4px;
  --radius-xs: 2px;
  --radius-pill: 4px;
  --radius-marker: 4px;
  --font-sans: "Inter", "Noto Sans SC", "PingFang SC", "Microsoft YaHei", "Segoe UI", sans-serif;
  --style-card-bar: 0;
  --style-title-gradient: 0;
  --glass-blur: 0px;
  --style-hover-scale: 1;
  --style-card-shadow: none;
  --style-heading-mark: flat;
  --style-btn-shape: var(--radius-pill);
  --style-border-width: 1px;
  --style-letter-spacing: -0.02em;
  --style-hover-transform: scale(1.012);
  --style-hover-shadow: var(--shadow-md);
  --style-hover-border: color-mix(in srgb, var(--accent) 22%, var(--border));
  --style-hover-duration: 0.2s;
  --style-hover-ease: cubic-bezier(0.4, 0, 0.2, 1);
  --style-hover-rest: none;
}

[data-ui-style="minimal"][data-theme="light"] {
--bg: #f1f5f9;
  --surface: #ffffff;
  --surface-elevated: #ffffff;
  --text: #0f172a;
  --muted: #64748b;
  --accent: #2563eb;
  --accent-hover: #1d4ed8;
  --accent-soft: #eff6ff;
  --accent-glow: rgba(37, 99, 235, 0.12);
  --accent-alt: #6366f1;
  --border: #e2e8f0;
  --code-bg: #f8fafc;
  --code-header: #f1f5f9;
  --shadow-sm: 0 1px 2px rgba(15, 23, 42, 0.05);
  --shadow-md: 0 4px 14px rgba(15, 23, 42, 0.08);
  --shadow-lg: 0 12px 32px rgba(15, 23, 42, 0.1);
  --success: #059669;
  --danger: #dc2626;
  --progress-gradient: linear-gradient(90deg, var(--accent), color-mix(in srgb, var(--accent) 75%, var(--accent-alt)));
  --bg-accent: radial-gradient(ellipse 70% 45% at 50% -15%, rgba(37, 99, 235, 0.06), transparent);
  --scrollbar-thumb: #cbd5e1;
  --style-hover-transform: scale(1.012);
  --style-hover-shadow: var(--shadow-md);
  --style-hover-border: color-mix(in srgb, var(--accent) 22%, var(--border));
  --style-hover-duration: 0.2s;
  --style-hover-ease: cubic-bezier(0.4, 0, 0.2, 1);
  --style-hover-rest: none;
}

[data-ui-style="minimal"][data-theme="dark"] {
--bg: #0f1419;
  --surface: #1a222d;
  --surface-elevated: #222c3a;
  --text: #e6edf3;
  --muted: #8b9cb3;
  --accent: #539bf5;
  --accent-hover: #6cb0ff;
  --accent-soft: #1c2836;
