}

[data-ui-style="minimal"] .topbar {
backdrop-filter: none;
  -webkit-backdrop-filter: none;
  background: var(--surface);
  box-shadow: none;
  border-bottom-width: 2px;
}

[data-ui-style="minimal"] .chapter-header {
box-shadow: none;
  border: 1px solid var(--border);
  border-bottom: 2px solid var(--accent);
}

[data-ui-style="minimal"] section[data-chapter].done .chapter-header {
border-left: 3px solid var(--accent);
  box-shadow: none;
}

[data-ui-style="minimal"] section[data-chapter].in-progress:not(.done) .chapter-header {
border-left: 3px solid color-mix(in srgb, var(--accent) 45%, var(--border));
