  padding-left: 0;
  border-bottom: 1px solid var(--border);
  padding-bottom: 0.35rem;
}

[data-ui-style="minimal"] .btn-mark-done:not(.is-done) {
background: var(--accent);
  box-shadow: none;
}

[data-ui-style="minimal"] .welcome-header h2,
[data-ui-style="minimal"] .course-title,
[data-ui-style="minimal"] .portal-hero h2 {
background: none;
  -webkit-text-fill-color: unset;
  color: var(--text);
  font-weight: 700;
}

[data-ui-style="minimal"] .course-title::before {
border-radius: var(--radius-sm);
  box-shadow: none;
}

[data-ui-style="minimal"] :is(.meta-card, .role-card, .course-card, .chapter .section-block, .code-block) {
box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

[data-ui-style="minimal"] .chapter-header {
box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
}

[data-ui-style="minimal"] section[data-chapter].done .chapter-header {
border-left: 3px solid var(--accent);
}

[data-ui-style="minimal"] section[data-chapter].in-progress:not(.done) .chapter-header {
border-left: 3px solid color-mix(in srgb, var(--accent) 45%, var(--border));
}

[data-ui-style="minimal"] .topbar {
backdrop-filter: none;
  box-shadow: none;
}

[data-ui-style="minimal"] .chapter .section-block > h3,
html[data-ui-style="minimal"] .chapter h3 {
border-left: none;
  border-bottom: 1px solid var(--border);
  border-radius: 0;
  padding-left: 0;
}

[data-ui-style="minimal"] body.page-course.page-chapter #sidebar {
border-right: 2px solid var(--border);
}

